-- =====================================================================
-- Sistema de Gestão Microlins — script.sql (Entrega 2)
-- SGBD: MySQL 8.0.16 ou superior (CHECK só é aplicado a partir desta versão)
-- Execução: rodar o arquivo INTEIRO, de uma só vez, em um servidor limpo
--           (ex.: mysql -u root -p < script.sql). O script recria o banco do zero.
--           No Workbench, use o botão do raio sem selecionar nenhum trecho,
--           pois a variável @data_ref precisa existir na mesma sessão.
-- Dicionário de referência: dicionario-dados-microlins.html v1.5 (31/10/2026)
--
-- Ordem do arquivo:
--   1. CREATE DATABASE / USE
--   2. CREATE TABLE (16 tabelas, com PK, FK, NOT NULL, UNIQUE, CHECK e DEFAULT)
--   3. INSERT INTO (dados fictícios)
--   4. UPDATE e DELETE (manutenção realista, com verificação antes e depois)
--   5. Consultas Gerenciais  (G01 a G14)
--   6. Consultas de Auditoria (A01 a A17)
--
-- ---------------------------------------------------------------------
-- RASTREABILIDADE (mesma numeração do README.md)
--
-- Problemas identificados (P)
--   P1 Alunos perdem o horário gravado no sistema
--   P2 Perda frequente de matrículas
--   P3 Sem histórico consolidado de pagamentos
--   P4 Sistema não justifica faltas, mesmo tendo a tela
--   P5 Sobreposição e lotação de salas e horários
--   P6 Endereços digitados de forma desorganizada
--       (prevenido por NOT NULL e CHECK em ALUNO; não há consulta, pois o banco não aceita endereço incompleto)
--
-- Regras de negócio (RN) verificadas pelas consultas de auditoria
--   RN01 Operação entre 08:00 e 18:00                                   (A10)
--   RN03 Turma extra só ter/qui entre 10:00 e 16:00                     (A14)
--   RN04 Capacidade da sala vale por dia e horário, somando as turmas   (A03)
--   RN05 Turma só existe com professor habilitado no curso              (A02)
--   RN06 Professor pode dar aula em até 2 turmas ao mesmo tempo         (A12)
--   RN08 Idade mínima de 14 anos na data da matrícula                   (A13)
--   RN09 O contrato é assinado por um responsável                       (A01)
--   RN22 Dados pessoais com finalidade restrita e consentimento         (A04)
--   RN23 Certificado exige a frequência mínima do curso                 (A05, A06, A07)
--   RN24 Cobrança PAGA tem o principal quitado, sem pagamento a maior   (A11)
--   RN25 A frequência pertence à matrícula da mesma turma da aula       (A08)
--   RN26 Aula regular ocorre somente nos dias da turma                  (A09)
--   RN27 Só se oferta turma com curso ativo e professor ativo           (A15)
--   RN28 Turma encerrada ou cancelada não mantém matrícula ativa        (A16)
--   RN29 Matrícula ativa gera cobranças                                 (A17)
--   RN02 (bloco de 2 horas) e as demais regras são garantidas por CHECK, FK e UNIQUE na criação das tabelas.
--
-- ---------------------------------------------------------------------
-- DADOS FICTÍCIOS E ANOMALIAS INTENCIONAIS
-- Todos os nomes, CPFs, telefones e e-mails são inventados. Os dados servem para testar
-- o modelo; não reproduzem a quantidade de alunos da unidade (477 por mês).
-- O banco contém 16 turmas, 100 alunos, 182 matrículas, 264 aulas, 3.394 registros
-- de frequência, 863 cobranças e 279 pagamentos, com cenários variados:
--   * turmas lotadas (EXCEL-2026-2T e BD-2026-2M ocupam 100% da sala de 15 lugares);
--   * alunos inadimplentes (cobranças VENCIDA), pagamentos atrasados com multa de 20% e
--     acréscimo diário de 20% sobre o último acréscimo (RN13) e pagamentos parciais em duas parcelas;
--   * alunos aprovados e reprovados por falta nas turmas encerradas;
--   * menores de idade com responsável (e um sem, de propósito).
-- Para que a auditoria tenha o que encontrar, foram plantadas inconsistências pontuais:
--   A01 aluno 99 (menor sem responsável)       A02 turma FIN-2026-2M (professora sem habilitação)
--   A03 sala 1 SEG/QUA 16h (WEB-2026-2T + WEB-2027-1T = 18 alunos) e sala 2 SEG/QUA/SEX 9h (DESIGN-2026-2M = 16)
--   A04 alunos 50 e 100                        A05/A06/A07 certificados de INFO-2026-1T e ING-2026-1T
--   A08 frequência de MKT-2026-2T em aula de ING-2026-2T      A09 aula de ING-2026-2T numa quarta-feira
--   A10 aula de MKT-2026-2T num domingo        A11 duas cobranças de INFO-2026-1T
--   A12 professora de WEB (3 turmas SEG/QUA 16h)              A13 aluno 96 (13 anos na matrícula)
--   A14 turma extra ROB-2027-1T numa sexta     A15 curso inativo em ROB-2027-1T
--   A16 matrícula ativa em MKT-2026-2M cancelada              A17 matrícula ativa sem cobrança em ROB-2027-1T
-- ---------------------------------------------------------------------
-- Premissas assumidas (o responsável informou o horário de 08:00 às 18:00, mas não os dias):
--   funcionamento de segunda a sexta; sala extra (25 lugares, só ter/qui) sem computadores (sal_qtd_computadores = 0, conforme o responsável);
--   todas as cobranças de teste são mensalidades (a escola informou que o material está embutido
--   na mensalidade); atraso: 20% da parcela no 1º dia (pag_multa) e, a cada dia seguinte, 20% do último acréscimo,
--   somados em pag_juros (ex.: parcela 290,00 → 348,00 no 1º dia, 359,60 no 2º, 361,92 no 3º), conforme informado; tur_tipo: REGULAR ou EXTRA; pro_regime: CLT, PJ ou HORISTA.
--   Acréscimo em relação ao dicionário v1.5: UNIQUE em CERTIFICADO.mat_id, para garantir o 1:1
--   do relacionamento RESULTA (certificado (0,1) por matrícula). Incluir no dicionário (índice único).
-- =====================================================================

-- =====================================================================
-- 1. CRIAÇÃO DO BANCO DE DADOS
-- =====================================================================
DROP DATABASE IF EXISTS microlins;  -- permite reexecutar o script do zero
CREATE DATABASE microlins CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
USE microlins;
SET NAMES utf8mb4;


-- =====================================================================
-- 2. CRIAÇÃO DAS TABELAS (tipos exatamente conforme o Dicionário de Dados v1.3)
--    Ordem: tabelas independentes primeiro; dependentes depois (respeita as FKs).
--    Convenção: toda FK usa ON DELETE RESTRICT e ON UPDATE RESTRICT (padrão explícito),
--    pois o dicionário (§6) proíbe apagar dados com histórico.
-- =====================================================================

CREATE TABLE HORARIO_FUNCIONAMENTO (
    hor_id              INTEGER      NOT NULL AUTO_INCREMENT,
    hor_dia_da_semana   VARCHAR(3)   NOT NULL,
    hor_abertura        TIME         NOT NULL,
    hor_fechamento      TIME         NOT NULL,
    CONSTRAINT pk_horario_funcionamento PRIMARY KEY (hor_id),
    CONSTRAINT uk_horario_dia UNIQUE (hor_dia_da_semana),
    CONSTRAINT ck_horario_dia CHECK (hor_dia_da_semana IN ('SEG','TER','QUA','QUI','SEX','SAB','DOM')),
    CONSTRAINT ck_horario_faixa CHECK (hor_abertura < hor_fechamento)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE SALA (
    sal_id               INTEGER      NOT NULL AUTO_INCREMENT,
    sal_identificacao    VARCHAR(30)  NOT NULL,
    sal_capacidade       INTEGER      NOT NULL,
    sal_qtd_computadores INTEGER      NOT NULL DEFAULT 0,
    CONSTRAINT pk_sala PRIMARY KEY (sal_id),
    CONSTRAINT uk_sala_identificacao UNIQUE (sal_identificacao),
    CONSTRAINT ck_sala_capacidade CHECK (sal_capacidade > 0),
    CONSTRAINT ck_sala_computadores CHECK (sal_qtd_computadores >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE CURSO (
    cur_id                INTEGER        NOT NULL AUTO_INCREMENT,
    cur_nome              VARCHAR(120)   NOT NULL,
    cur_carga_horaria     INTEGER        NOT NULL,
    cur_valor_mensalidade DECIMAL(10,2)  NOT NULL,
    cur_qtd_parcelas      INTEGER        NOT NULL,
    cur_frequencia_minima DECIMAL(5,2)   NOT NULL,
    cur_ativo             BOOLEAN        NOT NULL DEFAULT TRUE,
    CONSTRAINT pk_curso PRIMARY KEY (cur_id),
    CONSTRAINT uk_curso_nome UNIQUE (cur_nome),
    CONSTRAINT ck_curso_carga CHECK (cur_carga_horaria > 0),
    CONSTRAINT ck_curso_mensalidade CHECK (cur_valor_mensalidade > 0),
    CONSTRAINT ck_curso_parcelas CHECK (cur_qtd_parcelas >= 1),
    CONSTRAINT ck_curso_frequencia CHECK (cur_frequencia_minima BETWEEN 0 AND 100)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE PROFESSOR (
    pro_id           INTEGER       NOT NULL AUTO_INCREMENT,
    pro_nome         VARCHAR(120)  NOT NULL,
    pro_especialidade VARCHAR(100) NULL,
    pro_regime       VARCHAR(20)   NOT NULL,
    pro_ativo        BOOLEAN       NOT NULL DEFAULT TRUE,
    CONSTRAINT pk_professor PRIMARY KEY (pro_id),
    CONSTRAINT uk_professor_nome UNIQUE (pro_nome),
    CONSTRAINT ck_professor_regime CHECK (pro_regime IN ('CLT','PJ','HORISTA'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE FUNCIONARIO (
    fun_id     INTEGER       NOT NULL AUTO_INCREMENT,
    fun_nome   VARCHAR(120)  NOT NULL,
    fun_cargo  VARCHAR(60)   NOT NULL,
    fun_turno  VARCHAR(5)    NOT NULL,
    CONSTRAINT pk_funcionario PRIMARY KEY (fun_id),
    CONSTRAINT ck_funcionario_turno CHECK (fun_turno IN ('MANHA','TARDE','NOITE')),
    INDEX idx_funcionario_nome (fun_nome)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE RESPONSAVEL (
    res_id         INTEGER       NOT NULL AUTO_INCREMENT,
    res_cpf        CHAR(11)      NOT NULL,
    res_nome       VARCHAR(120)  NOT NULL,
    res_telefone   VARCHAR(20)   NOT NULL,
    res_parentesco VARCHAR(30)   NOT NULL,
    CONSTRAINT pk_responsavel PRIMARY KEY (res_id),
    CONSTRAINT uk_responsavel_cpf UNIQUE (res_cpf),
    CONSTRAINT ck_responsavel_cpf CHECK (res_cpf REGEXP '^[0-9]{11}$')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE ALUNO (
    alu_id                 INTEGER       NOT NULL AUTO_INCREMENT,
    alu_cpf                CHAR(11)      NOT NULL,
    res_id                 INTEGER       NULL,
    alu_nome               VARCHAR(120)  NOT NULL,
    alu_data_nascimento    DATE          NOT NULL,
    alu_email              VARCHAR(120)  NULL,
    alu_telefone           VARCHAR(20)   NOT NULL,
    alu_cep                CHAR(8)       NOT NULL,
    alu_logradouro         VARCHAR(150)  NOT NULL,
    alu_numero             VARCHAR(10)   NOT NULL,
    alu_bairro             VARCHAR(100)  NOT NULL,
    alu_consentimento_lgpd BOOLEAN       NOT NULL DEFAULT FALSE,
    alu_data_consentimento DATE          NULL,
    CONSTRAINT pk_aluno PRIMARY KEY (alu_id),
    CONSTRAINT uk_aluno_cpf UNIQUE (alu_cpf),
    CONSTRAINT ck_aluno_cpf CHECK (alu_cpf REGEXP '^[0-9]{11}$'),
    CONSTRAINT ck_aluno_cep CHECK (alu_cep REGEXP '^[0-9]{8}$'),
    INDEX idx_aluno_res_id (res_id),
    INDEX idx_aluno_nome (alu_nome),
    CONSTRAINT fk_aluno_responsavel FOREIGN KEY (res_id) REFERENCES RESPONSAVEL (res_id)
        ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE PROFESSOR_CURSO (
    pro_id INTEGER NOT NULL,
    cur_id INTEGER NOT NULL,
    CONSTRAINT pk_professor_curso PRIMARY KEY (pro_id, cur_id),
    INDEX idx_professor_curso_cur_id (cur_id),
    CONSTRAINT fk_professor_curso_professor FOREIGN KEY (pro_id) REFERENCES PROFESSOR (pro_id)
        ON DELETE RESTRICT ON UPDATE RESTRICT,
    CONSTRAINT fk_professor_curso_curso FOREIGN KEY (cur_id) REFERENCES CURSO (cur_id)
        ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE TURMA (
    tur_id          INTEGER      NOT NULL AUTO_INCREMENT,
    tur_codigo      VARCHAR(20)  NOT NULL,
    cur_id          INTEGER      NOT NULL,
    pro_id          INTEGER      NOT NULL,
    sal_id          INTEGER      NOT NULL,
    tur_tipo        VARCHAR(30)  NOT NULL DEFAULT 'REGULAR',
    tur_hora_inicio TIME         NOT NULL,
    tur_hora_fim    TIME         NOT NULL,
    tur_data_inicio DATE         NOT NULL,
    tur_data_fim    DATE         NULL,
    tur_situacao    VARCHAR(20)  NOT NULL DEFAULT 'ABERTA',
    CONSTRAINT pk_turma PRIMARY KEY (tur_id),
    CONSTRAINT uk_turma_codigo UNIQUE (tur_codigo),
    CONSTRAINT ck_turma_tipo CHECK (tur_tipo IN ('REGULAR','EXTRA')),
    CONSTRAINT ck_turma_situacao CHECK (tur_situacao IN ('ABERTA','EM_ANDAMENTO','ENCERRADA','CANCELADA')),
    CONSTRAINT ck_turma_horas CHECK (tur_hora_fim > tur_hora_inicio),
    CONSTRAINT ck_turma_bloco_2h CHECK (MOD(TIME_TO_SEC(tur_hora_fim) - TIME_TO_SEC(tur_hora_inicio), 7200) = 0),
    CONSTRAINT ck_turma_datas CHECK (tur_data_fim IS NULL OR tur_data_fim >= tur_data_inicio),
    INDEX idx_turma_cur_id (cur_id),
    INDEX idx_turma_pro_id (pro_id),
    INDEX idx_turma_sal_id (sal_id),
    INDEX idx_turma_situacao (tur_situacao),
    CONSTRAINT fk_turma_curso FOREIGN KEY (cur_id) REFERENCES CURSO (cur_id)
        ON DELETE RESTRICT ON UPDATE RESTRICT,
    CONSTRAINT fk_turma_professor FOREIGN KEY (pro_id) REFERENCES PROFESSOR (pro_id)
        ON DELETE RESTRICT ON UPDATE RESTRICT,
    CONSTRAINT fk_turma_sala FOREIGN KEY (sal_id) REFERENCES SALA (sal_id)
        ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE TURMA_HORARIO (
    tur_id INTEGER NOT NULL,
    hor_id INTEGER NOT NULL,
    CONSTRAINT pk_turma_horario PRIMARY KEY (tur_id, hor_id),
    INDEX idx_turma_horario_hor_id (hor_id),
    CONSTRAINT fk_turma_horario_turma FOREIGN KEY (tur_id) REFERENCES TURMA (tur_id)
        ON DELETE RESTRICT ON UPDATE RESTRICT,
    CONSTRAINT fk_turma_horario_horario FOREIGN KEY (hor_id) REFERENCES HORARIO_FUNCIONAMENTO (hor_id)
        ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE MATRICULA (
    mat_id                  INTEGER       NOT NULL AUTO_INCREMENT,
    alu_id                  INTEGER       NOT NULL,
    tur_id                  INTEGER       NOT NULL,
    fun_id                  INTEGER       NOT NULL,
    mat_data_registro       DATE          NOT NULL DEFAULT (CURDATE()),
    mat_status              VARCHAR(20)   NOT NULL DEFAULT 'ATIVA',
    mat_data_encerramento   DATE          NULL,
    mat_motivo_encerramento VARCHAR(200)  NULL,
    CONSTRAINT pk_matricula PRIMARY KEY (mat_id),
    CONSTRAINT ck_matricula_status CHECK (mat_status IN ('ATIVA','TRANCADA','CANCELADA','CONCLUIDA')),
    CONSTRAINT ck_matricula_encerramento CHECK (
        (mat_status = 'ATIVA' AND mat_data_encerramento IS NULL)
        OR (mat_status <> 'ATIVA' AND mat_data_encerramento IS NOT NULL)
    ),
    INDEX idx_matricula_alu_id (alu_id),
    INDEX idx_matricula_tur_id (tur_id),
    INDEX idx_matricula_fun_id (fun_id),
    INDEX idx_matricula_status (mat_status),
    CONSTRAINT fk_matricula_aluno FOREIGN KEY (alu_id) REFERENCES ALUNO (alu_id)
        ON DELETE RESTRICT ON UPDATE RESTRICT,
    CONSTRAINT fk_matricula_turma FOREIGN KEY (tur_id) REFERENCES TURMA (tur_id)
        ON DELETE RESTRICT ON UPDATE RESTRICT,
    CONSTRAINT fk_matricula_funcionario FOREIGN KEY (fun_id) REFERENCES FUNCIONARIO (fun_id)
        ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE AULA (
    aul_id          INTEGER      NOT NULL AUTO_INCREMENT,
    tur_id          INTEGER      NOT NULL,
    aul_data        DATE         NOT NULL,
    aul_tipo        VARCHAR(10)  NOT NULL DEFAULT 'REGULAR',
    aul_hora_inicio TIME         NOT NULL,
    aul_hora_fim    TIME         NOT NULL,
    CONSTRAINT pk_aula PRIMARY KEY (aul_id),
    CONSTRAINT ck_aula_tipo CHECK (aul_tipo IN ('REGULAR','REPOSICAO')),
    CONSTRAINT ck_aula_horas CHECK (aul_hora_fim > aul_hora_inicio),
    INDEX idx_aula_tur_data (tur_id, aul_data),
    CONSTRAINT fk_aula_turma FOREIGN KEY (tur_id) REFERENCES TURMA (tur_id)
        ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE FREQUENCIA (
    fre_id                 INTEGER       NOT NULL AUTO_INCREMENT,
    mat_id                 INTEGER       NOT NULL,
    aul_id                 INTEGER       NOT NULL,
    fre_situacao           VARCHAR(20)   NOT NULL DEFAULT 'PRESENTE',
    fre_justificativa      VARCHAR(200)  NULL,
    fre_data_justificativa DATE          NULL,
    CONSTRAINT pk_frequencia PRIMARY KEY (fre_id),
    CONSTRAINT uk_frequencia_mat_aul UNIQUE (mat_id, aul_id),
    CONSTRAINT ck_frequencia_situacao CHECK (fre_situacao IN ('PRESENTE','FALTA','FALTA_JUSTIFICADA')),
    CONSTRAINT ck_frequencia_justificativa CHECK (
        (fre_situacao = 'FALTA_JUSTIFICADA' AND fre_justificativa IS NOT NULL AND fre_data_justificativa IS NOT NULL)
        OR (fre_situacao <> 'FALTA_JUSTIFICADA' AND fre_justificativa IS NULL AND fre_data_justificativa IS NULL)
    ),
    INDEX idx_frequencia_aul_id (aul_id),
    CONSTRAINT fk_frequencia_matricula FOREIGN KEY (mat_id) REFERENCES MATRICULA (mat_id)
        ON DELETE RESTRICT ON UPDATE RESTRICT,
    CONSTRAINT fk_frequencia_aula FOREIGN KEY (aul_id) REFERENCES AULA (aul_id)
        ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE COBRANCA (
    cob_id              INTEGER        NOT NULL AUTO_INCREMENT,
    mat_id              INTEGER        NOT NULL,
    cob_tipo            VARCHAR(20)    NOT NULL,
    cob_numero_parcela  INTEGER        NOT NULL,
    cob_valor           DECIMAL(10,2)  NOT NULL,
    cob_status          VARCHAR(20)    NOT NULL DEFAULT 'ABERTA',
    cob_data_vencimento DATE           NOT NULL,
    CONSTRAINT pk_cobranca PRIMARY KEY (cob_id),
    CONSTRAINT ck_cobranca_tipo CHECK (cob_tipo IN ('MENSALIDADE','TAXA_MATRICULA','MATERIAL')),
    CONSTRAINT ck_cobranca_status CHECK (cob_status IN ('ABERTA','PAGA','VENCIDA','CANCELADA')),
    CONSTRAINT ck_cobranca_parcela CHECK (cob_numero_parcela >= 1),
    CONSTRAINT ck_cobranca_valor CHECK (cob_valor > 0),
    INDEX idx_cobranca_mat_id (mat_id),
    INDEX idx_cobranca_status (cob_status),
    INDEX idx_cobranca_vencimento (cob_data_vencimento),
    CONSTRAINT fk_cobranca_matricula FOREIGN KEY (mat_id) REFERENCES MATRICULA (mat_id)
        ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE PAGAMENTO (
    pag_id          INTEGER        NOT NULL AUTO_INCREMENT,
    cob_id          INTEGER        NOT NULL,
    pag_data_hora   DATETIME       NOT NULL DEFAULT CURRENT_TIMESTAMP,
    pag_valor_pago  DECIMAL(10,2)  NOT NULL,
    pag_multa       DECIMAL(10,2)  NOT NULL DEFAULT 0.00,
    pag_juros       DECIMAL(10,2)  NOT NULL DEFAULT 0.00,
    pag_forma       VARCHAR(20)    NOT NULL,
    CONSTRAINT pk_pagamento PRIMARY KEY (pag_id),
    CONSTRAINT ck_pagamento_valor CHECK (pag_valor_pago > 0),
    CONSTRAINT ck_pagamento_multa CHECK (pag_multa >= 0),
    CONSTRAINT ck_pagamento_juros CHECK (pag_juros >= 0),
    CONSTRAINT ck_pagamento_forma CHECK (pag_forma IN ('DINHEIRO','PIX','CARTAO_CREDITO','CARTAO_DEBITO','BOLETO')),
    INDEX idx_pagamento_cob_id (cob_id),
    INDEX idx_pagamento_data_hora (pag_data_hora),
    CONSTRAINT fk_pagamento_cobranca FOREIGN KEY (cob_id) REFERENCES COBRANCA (cob_id)
        ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE CERTIFICADO (
    cer_id                    INTEGER       NOT NULL AUTO_INCREMENT,
    cer_codigo                VARCHAR(30)   NOT NULL,
    mat_id                    INTEGER       NOT NULL,
    cer_data_emissao          DATE          NOT NULL DEFAULT (CURDATE()),
    cer_percentual_frequencia DECIMAL(5,2)  NOT NULL,
    CONSTRAINT pk_certificado PRIMARY KEY (cer_id),
    CONSTRAINT uk_certificado_codigo UNIQUE (cer_codigo),
    CONSTRAINT ck_certificado_percentual CHECK (cer_percentual_frequencia BETWEEN 0 AND 100),
    CONSTRAINT uk_certificado_mat UNIQUE (mat_id),   -- garante o 1:1 do relacionamento RESULTA (certificado (0,1) por matrícula)
    CONSTRAINT fk_certificado_matricula FOREIGN KEY (mat_id) REFERENCES MATRICULA (mat_id)
        ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;


-- =====================================================================
-- 3. INSERÇÃO DE DADOS (fictícios, em ordem de dependência das FKs)
-- =====================================================================

