-- =====================================================================
-- 4. UPDATE e DELETE — rotinas de manutenção com utilidade real
-- =====================================================================
SET SQL_SAFE_UPDATES = 0;
SET @data_ref = DATE('2026-10-30');   -- data de referência de todas as consultas (hoje fictício)

-- ---------------------------------------------------------------------
-- 4.1 UPDATE: atualização diária de inadimplência (RN17)
-- Cobranças ABERTAS cujo vencimento já passou devem virar VENCIDA.
-- ---------------------------------------------------------------------
-- Antes
SELECT cob_status AS situacao_antes, COUNT(*) AS qtd_cobrancas, SUM(cob_valor) AS valor_total
FROM COBRANCA
WHERE cob_status IN ('ABERTA','VENCIDA') AND cob_data_vencimento < @data_ref
GROUP BY cob_status;

UPDATE COBRANCA
SET cob_status = 'VENCIDA'
WHERE cob_status = 'ABERTA'
  AND cob_data_vencimento < @data_ref;

-- Depois (não deve restar cobrança ABERTA vencida)
SELECT cob_status AS situacao_depois, COUNT(*) AS qtd_cobrancas, SUM(cob_valor) AS valor_total
FROM COBRANCA
WHERE cob_status IN ('ABERTA','VENCIDA') AND cob_data_vencimento < @data_ref
GROUP BY cob_status;

-- ---------------------------------------------------------------------
-- 4.2 UPDATE: encerramento de turmas cujo prazo terminou (turma EXCEL-2026-1T ficou
-- "EM_ANDAMENTO" após a data final) e conclusão das matrículas que ainda estavam ativas.
-- ---------------------------------------------------------------------
-- Antes
SELECT t.tur_codigo, t.tur_situacao, t.tur_data_fim, COUNT(m.mat_id) AS matriculas_ativas
FROM TURMA t
JOIN MATRICULA m ON m.tur_id = t.tur_id AND m.mat_status = 'ATIVA'
WHERE t.tur_data_fim < @data_ref AND t.tur_situacao = 'EM_ANDAMENTO'
GROUP BY t.tur_id, t.tur_codigo, t.tur_situacao, t.tur_data_fim;

UPDATE TURMA
SET tur_situacao = 'ENCERRADA'
WHERE tur_situacao = 'EM_ANDAMENTO'
  AND tur_data_fim < @data_ref;

UPDATE MATRICULA m
JOIN TURMA t ON t.tur_id = m.tur_id
SET m.mat_status = 'CONCLUIDA',
    m.mat_data_encerramento = t.tur_data_fim
WHERE t.tur_situacao = 'ENCERRADA'
  AND m.mat_status = 'ATIVA';

-- Depois
SELECT t.tur_codigo, t.tur_situacao, m.mat_status, COUNT(*) AS qtd_matriculas
FROM TURMA t
JOIN MATRICULA m ON m.tur_id = t.tur_id
WHERE t.tur_codigo = 'EXCEL-2026-1T'
GROUP BY t.tur_codigo, t.tur_situacao, m.mat_status;

-- ---------------------------------------------------------------------
-- 4.3 INSERT ... SELECT: emissão em lote de certificados (RN23) para os concluintes
-- de EXCEL-2026-1T com frequência igual ou superior ao mínimo do curso.
-- Falta justificada conta como presença (RN16).
-- ---------------------------------------------------------------------
INSERT INTO CERTIFICADO (cer_codigo, mat_id, cer_data_emissao, cer_percentual_frequencia)
SELECT CONCAT('MIC-2026-', LPAD(m.mat_id, 6, '0')),
       m.mat_id,
       @data_ref,
       ROUND(100 * SUM(f.fre_situacao IN ('PRESENTE','FALTA_JUSTIFICADA')) / COUNT(*), 2)
FROM MATRICULA m
JOIN TURMA t    ON t.tur_id = m.tur_id
JOIN CURSO c    ON c.cur_id = t.cur_id
JOIN AULA a     ON a.tur_id = m.tur_id
JOIN FREQUENCIA f ON f.mat_id = m.mat_id AND f.aul_id = a.aul_id
WHERE t.tur_codigo = 'EXCEL-2026-1T'
  AND m.mat_status = 'CONCLUIDA'
  AND NOT EXISTS (SELECT 1 FROM CERTIFICADO ce WHERE ce.mat_id = m.mat_id)
GROUP BY m.mat_id, c.cur_frequencia_minima
HAVING 100 * SUM(f.fre_situacao IN ('PRESENTE','FALTA_JUSTIFICADA')) / COUNT(*) >= c.cur_frequencia_minima;

-- Verificação: certificados emitidos e concluintes reprovados por falta na turma
SELECT a.alu_nome,
       ROUND(100 * SUM(f.fre_situacao IN ('PRESENTE','FALTA_JUSTIFICADA')) / COUNT(*), 2) AS frequencia_pct,
       CASE WHEN ce.cer_id IS NULL THEN 'Reprovado por falta' ELSE ce.cer_codigo END AS resultado
FROM MATRICULA m
JOIN TURMA t ON t.tur_id = m.tur_id
JOIN ALUNO a ON a.alu_id = m.alu_id
JOIN FREQUENCIA f ON f.mat_id = m.mat_id
LEFT JOIN CERTIFICADO ce ON ce.mat_id = m.mat_id
WHERE t.tur_codigo = 'EXCEL-2026-1T' AND m.mat_status = 'CONCLUIDA'
GROUP BY m.mat_id, a.alu_nome, ce.cer_id, ce.cer_codigo
ORDER BY frequencia_pct DESC;

-- ---------------------------------------------------------------------
-- 4.4 DELETE: limpeza de dados sem histórico (permitido pelo dicionário §6, tabelas associativas).
-- (a) Remove os dias de funcionamento de turmas CANCELADAS, que não terão mais aula.
-- (b) Remove habilitações de professores inativos.
-- ---------------------------------------------------------------------
SELECT COUNT(*) AS dias_de_turmas_canceladas_antes
FROM TURMA_HORARIO
WHERE tur_id IN (SELECT tur_id FROM TURMA WHERE tur_situacao = 'CANCELADA');

DELETE FROM TURMA_HORARIO
WHERE tur_id IN (SELECT tur_id FROM TURMA WHERE tur_situacao = 'CANCELADA');

DELETE FROM PROFESSOR_CURSO
WHERE pro_id IN (SELECT pro_id FROM PROFESSOR WHERE pro_ativo = FALSE);

SELECT (SELECT COUNT(*) FROM TURMA_HORARIO) AS total_turma_horario_depois,
       (SELECT COUNT(*) FROM PROFESSOR_CURSO) AS total_habilitacoes_depois;

SET SQL_SAFE_UPDATES = 1;

-- =====================================================================
-- 5. CONSULTAS GERENCIAIS
-- Convenção: principal pago = pag_valor_pago - pag_multa - pag_juros.
-- Frequência = (PRESENTE + FALTA_JUSTIFICADA) / total de registros (RN16).
-- =====================================================================

-- G01 Qual o faturamento total previsto por turma neste mês?
-- Atende: P3 (sem histórico consolidado de pagamentos: previsão de receita por turma)
SELECT t.tur_codigo AS turma,
       c.cur_nome AS curso,
       COUNT(*) AS qtd_mensalidades_no_mes,
       SUM(cb.cob_valor) AS faturamento_previsto
FROM COBRANCA cb
JOIN MATRICULA m ON m.mat_id = cb.mat_id
JOIN TURMA t     ON t.tur_id = m.tur_id
JOIN CURSO c     ON c.cur_id = t.cur_id
WHERE cb.cob_tipo = 'MENSALIDADE'
  AND cb.cob_status <> 'CANCELADA'
  AND cb.cob_data_vencimento BETWEEN DATE_SUB(@data_ref, INTERVAL DAYOFMONTH(@data_ref) - 1 DAY) AND LAST_DAY(@data_ref)
GROUP BY t.tur_id, t.tur_codigo, c.cur_nome
ORDER BY faturamento_previsto DESC;

-- G02 Qual o valor em atraso e quantos alunos estão inadimplentes em cada curso?
-- Atende: P3 (sem histórico consolidado de pagamentos: inadimplência por curso)
SELECT c.cur_nome AS curso,
       COUNT(DISTINCT m.alu_id) AS alunos_inadimplentes,
       COUNT(*) AS cobrancas_em_atraso,
       SUM(cb.cob_valor - IFNULL(p.principal_pago, 0)) AS valor_em_atraso
FROM COBRANCA cb
JOIN MATRICULA m ON m.mat_id = cb.mat_id
JOIN TURMA t     ON t.tur_id = m.tur_id
JOIN CURSO c     ON c.cur_id = t.cur_id
LEFT JOIN (SELECT cob_id, SUM(pag_valor_pago - pag_multa - pag_juros) AS principal_pago
           FROM PAGAMENTO GROUP BY cob_id) p ON p.cob_id = cb.cob_id
WHERE cb.cob_status IN ('ABERTA','VENCIDA')
  AND cb.cob_data_vencimento < @data_ref
GROUP BY c.cur_id, c.cur_nome
ORDER BY valor_em_atraso DESC;

-- G03 Qual a taxa de ocupação de cada turma em relação à capacidade da sala e quais estão lotadas?
-- Atende: P5 (sobreposição e lotação de salas e horários)
SELECT t.tur_codigo AS turma,
       s.sal_identificacao AS sala,
       s.sal_capacidade AS capacidade,
       COUNT(m.mat_id) AS matriculas_ativas,
       ROUND(100 * COUNT(m.mat_id) / s.sal_capacidade, 1) AS taxa_ocupacao_pct,
       CASE WHEN COUNT(m.mat_id) > s.sal_capacidade THEN 'ACIMA DA CAPACIDADE'
            WHEN COUNT(m.mat_id) = s.sal_capacidade THEN 'LOTADA'
            WHEN COUNT(m.mat_id) >= 0.8 * s.sal_capacidade THEN 'QUASE LOTADA'
            ELSE 'COM VAGAS' END AS situacao_vagas
FROM TURMA t
JOIN SALA s ON s.sal_id = t.sal_id
LEFT JOIN MATRICULA m ON m.tur_id = t.tur_id AND m.mat_status = 'ATIVA'
WHERE t.tur_situacao IN ('ABERTA','EM_ANDAMENTO')
GROUP BY t.tur_id, t.tur_codigo, s.sal_identificacao, s.sal_capacidade
ORDER BY taxa_ocupacao_pct DESC;

-- G04 Quais alunos ativos estão com frequência abaixo do mínimo exigido pelo curso?
-- Atende: P4 (falta e justificativa de faltas: alunos em risco de reprovação)
WITH frequencia_por_matricula AS (
    SELECT f.mat_id,
           COUNT(*) AS aulas_registradas,
           SUM(f.fre_situacao IN ('PRESENTE','FALTA_JUSTIFICADA')) AS presencas
    FROM FREQUENCIA f
    JOIN MATRICULA m ON m.mat_id = f.mat_id
    JOIN AULA a      ON a.aul_id = f.aul_id AND a.tur_id = m.tur_id
    GROUP BY f.mat_id
)
SELECT al.alu_nome AS aluno,
       t.tur_codigo AS turma,
       c.cur_nome AS curso,
       fm.aulas_registradas,
       fm.presencas,
       ROUND(100 * fm.presencas / fm.aulas_registradas, 2) AS frequencia_pct,
       c.cur_frequencia_minima AS minimo_exigido_pct
FROM frequencia_por_matricula fm
JOIN MATRICULA m ON m.mat_id = fm.mat_id
JOIN ALUNO al    ON al.alu_id = m.alu_id
JOIN TURMA t     ON t.tur_id = m.tur_id
JOIN CURSO c     ON c.cur_id = t.cur_id
WHERE m.mat_status = 'ATIVA'
  AND t.tur_situacao = 'EM_ANDAMENTO'
  AND 100 * fm.presencas / fm.aulas_registradas < c.cur_frequencia_minima
ORDER BY frequencia_pct ASC;

-- G05 Quanto foi recebido por mês e por forma de pagamento?
-- Atende: P3 (sem histórico consolidado de pagamentos: recebimentos por mês e forma)
SELECT DATE_FORMAT(p.pag_data_hora, '%Y-%m') AS mes,
       p.pag_forma AS forma_pagamento,
       COUNT(*) AS qtd_pagamentos,
       SUM(p.pag_valor_pago) AS total_recebido
FROM PAGAMENTO p
GROUP BY DATE_FORMAT(p.pag_data_hora, '%Y-%m'), p.pag_forma
ORDER BY mes, total_recebido DESC;

-- G06 Qual o desempenho de cada professor (turmas, alunos atendidos e frequência média)?
-- Atende: P4 (falta e justificativa de faltas: frequência por professor)
SELECT pr.pro_nome AS professor,
       pr.pro_regime AS regime,
       COUNT(DISTINCT t.tur_id) AS turmas_lecionadas,
       COUNT(DISTINCT m.mat_id) AS matriculas_atendidas,
       ROUND(100 * SUM(f.fre_situacao IN ('PRESENTE','FALTA_JUSTIFICADA')) / NULLIF(COUNT(f.fre_id), 0), 2) AS frequencia_media_pct
FROM PROFESSOR pr
JOIN TURMA t ON t.pro_id = pr.pro_id
LEFT JOIN MATRICULA m ON m.tur_id = t.tur_id
LEFT JOIN FREQUENCIA f ON f.mat_id = m.mat_id
GROUP BY pr.pro_id, pr.pro_nome, pr.pro_regime
ORDER BY frequencia_media_pct DESC;

-- G07 Qual a taxa de evasão (cancelamentos e trancamentos) de cada curso?
-- Atende: P2 (perda frequente de matrículas: evasão por curso)
SELECT c.cur_nome AS curso,
       COUNT(m.mat_id) AS total_matriculas,
       SUM(m.mat_status = 'CANCELADA') AS canceladas,
       SUM(m.mat_status = 'TRANCADA') AS trancadas,
       ROUND(100 * SUM(m.mat_status IN ('CANCELADA','TRANCADA')) / COUNT(m.mat_id), 2) AS taxa_evasao_pct
FROM CURSO c
JOIN TURMA t     ON t.cur_id = c.cur_id
JOIN MATRICULA m ON m.tur_id = t.tur_id
GROUP BY c.cur_id, c.cur_nome
ORDER BY taxa_evasao_pct DESC;

-- G08 Qual o ranking de cursos por receita de mensalidades, taxas e material efetivamente recebida?
-- Atende: P3 (sem histórico consolidado de pagamentos: receita por curso)
WITH receita_por_curso AS (
    SELECT c.cur_id,
           c.cur_nome,
           SUM(p.pag_valor_pago - p.pag_multa - p.pag_juros) AS receita_principal,
           COUNT(DISTINCT m.alu_id) AS alunos_pagantes
    FROM PAGAMENTO p
    JOIN COBRANCA cb ON cb.cob_id = p.cob_id
    JOIN MATRICULA m ON m.mat_id = cb.mat_id
    JOIN TURMA t     ON t.tur_id = m.tur_id
    JOIN CURSO c     ON c.cur_id = t.cur_id
    GROUP BY c.cur_id, c.cur_nome
)
SELECT RANK() OVER (ORDER BY receita_principal DESC) AS posicao,
       cur_nome AS curso,
       receita_principal,
       alunos_pagantes,
       ROUND(receita_principal / alunos_pagantes, 2) AS receita_por_aluno,
       ROUND(100 * receita_principal / SUM(receita_principal) OVER (), 2) AS participacao_pct
FROM receita_por_curso
ORDER BY posicao;

-- G09 Há quanto tempo o saldo devedor está em atraso (faixas de aging)?
-- Atende: P3 (sem histórico consolidado de pagamentos: aging da inadimplência)
SELECT faixa_atraso,
       COUNT(*) AS qtd_cobrancas,
       SUM(saldo) AS saldo_devedor
FROM (
    SELECT CASE WHEN DATEDIFF(@data_ref, cb.cob_data_vencimento) <= 30 THEN '1 a 30 dias'
                WHEN DATEDIFF(@data_ref, cb.cob_data_vencimento) <= 60 THEN '31 a 60 dias'
                WHEN DATEDIFF(@data_ref, cb.cob_data_vencimento) <= 90 THEN '61 a 90 dias'
                ELSE 'Acima de 90 dias' END AS faixa_atraso,
           cb.cob_valor - IFNULL(p.principal_pago, 0) AS saldo
    FROM COBRANCA cb
    LEFT JOIN (SELECT cob_id, SUM(pag_valor_pago - pag_multa - pag_juros) AS principal_pago
               FROM PAGAMENTO GROUP BY cob_id) p ON p.cob_id = cb.cob_id
    WHERE cb.cob_status IN ('ABERTA','VENCIDA')
      AND cb.cob_data_vencimento < @data_ref
) atrasadas
GROUP BY faixa_atraso
ORDER BY FIELD(faixa_atraso, '1 a 30 dias', '31 a 60 dias', '61 a 90 dias', 'Acima de 90 dias');

-- G10 Quantas matrículas cada funcionário gerou, quantas seguem ativas e qual a taxa de cancelamento?
-- Atende: P2 (perda frequente de matrículas: matrículas e evasão por funcionário)
SELECT fu.fun_nome AS funcionario,
       fu.fun_cargo AS cargo,
       fu.fun_turno AS turno,
       COUNT(m.mat_id) AS matriculas_geradas,
       SUM(m.mat_status = 'ATIVA') AS matriculas_ativas,
       SUM(m.mat_status = 'CONCLUIDA') AS matriculas_concluidas,
       SUM(m.mat_status IN ('CANCELADA','TRANCADA')) AS matriculas_evadidas,
       ROUND(100 * SUM(m.mat_status IN ('CANCELADA','TRANCADA')) / NULLIF(COUNT(m.mat_id), 0), 2) AS taxa_evasao_pct
FROM FUNCIONARIO fu
LEFT JOIN MATRICULA m ON m.fun_id = fu.fun_id
GROUP BY fu.fun_id, fu.fun_nome, fu.fun_cargo, fu.fun_turno
ORDER BY matriculas_geradas DESC, fu.fun_nome;

-- G11 Quantas horas por semana cada sala ocupa em relação ao horário de funcionamento de cada dia?
-- Atende: P5 (sobreposição e lotação de salas e horários: uso das salas)
SELECT h.hor_dia_da_semana AS dia,
       s.sal_identificacao AS sala,
       COUNT(DISTINCT t.tur_id) AS turmas,
       SUM(TIME_TO_SEC(t.tur_hora_fim) - TIME_TO_SEC(t.tur_hora_inicio)) / 3600 AS horas_ocupadas,
       (TIME_TO_SEC(h.hor_fechamento) - TIME_TO_SEC(h.hor_abertura)) / 3600 AS horas_disponiveis,
       ROUND(100 * SUM(TIME_TO_SEC(t.tur_hora_fim) - TIME_TO_SEC(t.tur_hora_inicio))
             / (TIME_TO_SEC(h.hor_fechamento) - TIME_TO_SEC(h.hor_abertura)), 1) AS ocupacao_pct
FROM TURMA_HORARIO th
JOIN HORARIO_FUNCIONAMENTO h ON h.hor_id = th.hor_id
JOIN TURMA t ON t.tur_id = th.tur_id
JOIN SALA s  ON s.sal_id = t.sal_id
WHERE t.tur_situacao = 'EM_ANDAMENTO'
GROUP BY h.hor_id, h.hor_dia_da_semana, h.hor_abertura, h.hor_fechamento, s.sal_id, s.sal_identificacao
ORDER BY h.hor_id, s.sal_identificacao;

-- G12 Quantos concluintes foram aprovados e reprovados por falta em cada curso?
-- Atende: P4 (falta e justificativa de faltas: aprovação e reprovação por falta)
WITH frequencia_por_matricula AS (
    SELECT f.mat_id,
           COUNT(*) AS aulas_registradas,
           SUM(f.fre_situacao IN ('PRESENTE','FALTA_JUSTIFICADA')) AS presencas
    FROM FREQUENCIA f
    JOIN MATRICULA m ON m.mat_id = f.mat_id
    JOIN AULA a      ON a.aul_id = f.aul_id AND a.tur_id = m.tur_id
    GROUP BY f.mat_id
),
resultado AS (
    SELECT c.cur_id,
           c.cur_nome,
           (100 * fm.presencas / fm.aulas_registradas >= c.cur_frequencia_minima) AS aprovado
    FROM MATRICULA m
    JOIN TURMA t ON t.tur_id = m.tur_id
    JOIN CURSO c ON c.cur_id = t.cur_id
    JOIN frequencia_por_matricula fm ON fm.mat_id = m.mat_id
    WHERE t.tur_situacao = 'ENCERRADA'
      AND m.mat_status = 'CONCLUIDA'
)
SELECT cur_nome AS curso,
       COUNT(*) AS concluintes,
       SUM(aprovado) AS aprovados_por_frequencia,
       COUNT(*) - SUM(aprovado) AS reprovados_por_falta,
       ROUND(100 * SUM(aprovado) / COUNT(*), 2) AS taxa_aprovacao_pct
FROM resultado
GROUP BY cur_id, cur_nome
ORDER BY taxa_aprovacao_pct ASC;

-- G13 Quanto a escola arrecadou de multa e juros por mês?
-- Atende: P3 (sem histórico consolidado de pagamentos: multa e juros por atraso)
SELECT DATE_FORMAT(pag_data_hora, '%Y-%m') AS mes,
       COUNT(*) AS qtd_pagamentos,
       SUM(pag_multa + pag_juros > 0) AS pagamentos_com_atraso,
       SUM(pag_multa) AS total_multas,
       SUM(pag_juros) AS total_juros,
       SUM(pag_multa + pag_juros) AS total_encargos
FROM PAGAMENTO
GROUP BY DATE_FORMAT(pag_data_hora, '%Y-%m')
ORDER BY mes;

-- G14 Quem são os 10 maiores devedores e qual o contato para cobrança (responsável, se menor)?
-- Atende: P3 (sem histórico consolidado de pagamentos: maiores devedores)
WITH devedores AS (
    SELECT m.alu_id,
           COUNT(*) AS cobrancas_em_atraso,
           SUM(cb.cob_valor - IFNULL(p.principal_pago, 0)) AS saldo_devedor,
           MIN(cb.cob_data_vencimento) AS vencimento_mais_antigo
    FROM COBRANCA cb
    JOIN MATRICULA m ON m.mat_id = cb.mat_id
    LEFT JOIN (SELECT cob_id, SUM(pag_valor_pago - pag_multa - pag_juros) AS principal_pago
               FROM PAGAMENTO GROUP BY cob_id) p ON p.cob_id = cb.cob_id
    WHERE cb.cob_status IN ('ABERTA','VENCIDA')
      AND cb.cob_data_vencimento < @data_ref
    GROUP BY m.alu_id
)
SELECT a.alu_nome AS aluno,
       IFNULL(r.res_nome, a.alu_nome) AS contato_para_cobranca,
       IFNULL(r.res_telefone, a.alu_telefone) AS telefone_para_cobranca,
       d.cobrancas_em_atraso,
       d.saldo_devedor,
       d.vencimento_mais_antigo
FROM devedores d
JOIN ALUNO a ON a.alu_id = d.alu_id
LEFT JOIN RESPONSAVEL r ON r.res_id = a.res_id
ORDER BY d.saldo_devedor DESC, a.alu_nome
LIMIT 10;


-- =====================================================================
-- 6. CONSULTAS DE AUDITORIA
-- Cada consulta lista as linhas que VIOLAM a regra. Resultado vazio = regra respeitada.
-- Neste conjunto de dados, cada consulta retorna ao menos uma linha de propósito
-- (inconsistências plantadas, descritas no cabeçalho do arquivo).
-- =====================================================================

-- A01 Existe aluno menor de 18 anos sem responsável legal cadastrado?
-- Verifica: RN09 (contrato assinado pelo responsável)
SELECT a.alu_id, a.alu_nome, a.alu_data_nascimento,
       TIMESTAMPDIFF(YEAR, a.alu_data_nascimento, @data_ref) AS idade
FROM ALUNO a
WHERE TIMESTAMPDIFF(YEAR, a.alu_data_nascimento, @data_ref) < 18
  AND a.res_id IS NULL;

-- A02 Existe turma lecionada por professor sem habilitação no curso?
-- Verifica: RN05 (professor habilitado no curso)
SELECT t.tur_codigo, c.cur_nome AS curso, pr.pro_nome AS professor
FROM TURMA t
JOIN CURSO c      ON c.cur_id = t.cur_id
JOIN PROFESSOR pr ON pr.pro_id = t.pro_id
WHERE NOT EXISTS (SELECT 1 FROM PROFESSOR_CURSO pc
                  WHERE pc.pro_id = t.pro_id AND pc.cur_id = t.cur_id);

-- A03 Existe sala com mais alunos ativos do que a capacidade, somando todas as turmas do mesmo dia e horário?
-- Verifica: RN04 (capacidade da sala por dia e horário)
SELECT s.sal_identificacao AS sala,
       h.hor_dia_da_semana AS dia,
       t.tur_hora_inicio AS inicio,
       t.tur_hora_fim AS fim,
       GROUP_CONCAT(DISTINCT t.tur_codigo ORDER BY t.tur_codigo SEPARATOR ', ') AS turmas,
       COUNT(m.mat_id) AS alunos_ativos,
       s.sal_capacidade,
       COUNT(m.mat_id) - s.sal_capacidade AS excedente
FROM TURMA t
JOIN SALA s ON s.sal_id = t.sal_id
JOIN TURMA_HORARIO th ON th.tur_id = t.tur_id
JOIN HORARIO_FUNCIONAMENTO h ON h.hor_id = th.hor_id
JOIN MATRICULA m ON m.tur_id = t.tur_id AND m.mat_status = 'ATIVA'
WHERE t.tur_situacao IN ('ABERTA','EM_ANDAMENTO')
GROUP BY s.sal_id, s.sal_identificacao, s.sal_capacidade, h.hor_id, h.hor_dia_da_semana, t.tur_hora_inicio, t.tur_hora_fim
HAVING COUNT(m.mat_id) > s.sal_capacidade
ORDER BY excedente DESC, s.sal_identificacao, h.hor_id;

-- A04 Existe aluno com consentimento LGPD incoerente com a data de consentimento?
-- Verifica: RN22 (dados pessoais com finalidade e consentimento registrados)
SELECT a.alu_id, a.alu_nome, a.alu_consentimento_lgpd, a.alu_data_consentimento,
       CASE WHEN a.alu_consentimento_lgpd = TRUE AND a.alu_data_consentimento IS NULL
            THEN 'Consentimento registrado sem data'
            ELSE 'Data de consentimento sem consentimento' END AS inconsistencia
FROM ALUNO a
WHERE (a.alu_consentimento_lgpd = TRUE  AND a.alu_data_consentimento IS NULL)
   OR (a.alu_consentimento_lgpd = FALSE AND a.alu_data_consentimento IS NOT NULL);

-- A05 Existe certificado emitido com frequência abaixo do mínimo do curso?
-- Verifica: RN23 (certificado exige a frequência mínima do curso)
SELECT ce.cer_codigo, al.alu_nome AS aluno, c.cur_nome AS curso,
       ce.cer_percentual_frequencia, c.cur_frequencia_minima
FROM CERTIFICADO ce
JOIN MATRICULA m ON m.mat_id = ce.mat_id
JOIN ALUNO al    ON al.alu_id = m.alu_id
JOIN TURMA t     ON t.tur_id = m.tur_id
JOIN CURSO c     ON c.cur_id = t.cur_id
WHERE ce.cer_percentual_frequencia < c.cur_frequencia_minima;

-- A06 Existe certificado cujo percentual gravado difere do percentual apurado na frequência?
-- Verifica: RN23 (percentual do certificado reflete a frequência real)
WITH apurado AS (
    SELECT f.mat_id,
           ROUND(100 * SUM(f.fre_situacao IN ('PRESENTE','FALTA_JUSTIFICADA')) / COUNT(*), 2) AS percentual_apurado
    FROM FREQUENCIA f
    JOIN MATRICULA m ON m.mat_id = f.mat_id
    JOIN AULA a      ON a.aul_id = f.aul_id AND a.tur_id = m.tur_id
    GROUP BY f.mat_id
)
SELECT ce.cer_codigo, al.alu_nome AS aluno,
       ce.cer_percentual_frequencia AS percentual_gravado,
       ap.percentual_apurado
FROM CERTIFICADO ce
JOIN MATRICULA m ON m.mat_id = ce.mat_id
JOIN ALUNO al    ON al.alu_id = m.alu_id
JOIN apurado ap  ON ap.mat_id = ce.mat_id
WHERE ABS(ce.cer_percentual_frequencia - ap.percentual_apurado) > 0.01;

-- A07 Existe concluinte com frequência suficiente que ficou sem certificado?
-- Verifica: RN23 (concluinte apto deve receber certificado)
WITH apurado AS (
    SELECT f.mat_id,
           ROUND(100 * SUM(f.fre_situacao IN ('PRESENTE','FALTA_JUSTIFICADA')) / COUNT(*), 2) AS percentual_apurado
    FROM FREQUENCIA f
    JOIN MATRICULA m ON m.mat_id = f.mat_id
    JOIN AULA a      ON a.aul_id = f.aul_id AND a.tur_id = m.tur_id
    GROUP BY f.mat_id
)
SELECT m.mat_id, al.alu_nome AS aluno, t.tur_codigo, c.cur_nome AS curso,
       ap.percentual_apurado, c.cur_frequencia_minima
FROM MATRICULA m
JOIN ALUNO al   ON al.alu_id = m.alu_id
JOIN TURMA t    ON t.tur_id = m.tur_id
JOIN CURSO c    ON c.cur_id = t.cur_id
JOIN apurado ap ON ap.mat_id = m.mat_id
WHERE m.mat_status = 'CONCLUIDA'
  AND ap.percentual_apurado >= c.cur_frequencia_minima
  AND NOT EXISTS (SELECT 1 FROM CERTIFICADO ce WHERE ce.mat_id = m.mat_id);

-- A08 Existe registro de frequência de uma matrícula em aula de outra turma?
-- Verifica: RN25 (frequência pertence à matrícula da mesma turma da aula)
SELECT f.fre_id, m.mat_id, al.alu_nome AS aluno,
       tm.tur_codigo AS turma_da_matricula,
       ta.tur_codigo AS turma_da_aula,
       a.aul_data
FROM FREQUENCIA f
JOIN MATRICULA m ON m.mat_id = f.mat_id
JOIN AULA a      ON a.aul_id = f.aul_id
JOIN ALUNO al    ON al.alu_id = m.alu_id
JOIN TURMA tm    ON tm.tur_id = m.tur_id
JOIN TURMA ta    ON ta.tur_id = a.tur_id
WHERE m.tur_id <> a.tur_id;

-- A09 Existe aula regular marcada em dia da semana em que a turma não funciona?
-- Verifica: RN26 (aula regular ocorre nos dias da turma)
SELECT a.aul_id, t.tur_codigo, a.aul_data,
       ELT(DAYOFWEEK(a.aul_data), 'DOM','SEG','TER','QUA','QUI','SEX','SAB') AS dia_da_semana
FROM AULA a
JOIN TURMA t ON t.tur_id = a.tur_id
WHERE a.aul_tipo = 'REGULAR'
  AND NOT EXISTS (
      SELECT 1
      FROM TURMA_HORARIO th
      JOIN HORARIO_FUNCIONAMENTO h ON h.hor_id = th.hor_id
      WHERE th.tur_id = a.tur_id
        AND h.hor_dia_da_semana = ELT(DAYOFWEEK(a.aul_data), 'DOM','SEG','TER','QUA','QUI','SEX','SAB')
  );

-- A10 Existe aula em dia ou horário em que a escola não funciona?
-- Verifica: RN01 (operação somente dentro do horário de funcionamento)
SELECT a.aul_id, t.tur_codigo, a.aul_tipo, a.aul_data,
       ELT(DAYOFWEEK(a.aul_data), 'DOM','SEG','TER','QUA','QUI','SEX','SAB') AS dia_da_semana,
       a.aul_hora_inicio, a.aul_hora_fim,
       CASE WHEN h.hor_id IS NULL THEN 'Escola fechada no dia'
            ELSE 'Fora do horário de funcionamento' END AS motivo
FROM AULA a
JOIN TURMA t ON t.tur_id = a.tur_id
LEFT JOIN HORARIO_FUNCIONAMENTO h
       ON h.hor_dia_da_semana = ELT(DAYOFWEEK(a.aul_data), 'DOM','SEG','TER','QUA','QUI','SEX','SAB')
WHERE h.hor_id IS NULL
   OR a.aul_hora_inicio < h.hor_abertura
   OR a.aul_hora_fim > h.hor_fechamento;

-- A11 Existe cobrança cujo status não corresponde ao que foi efetivamente pago?
-- Verifica: RN24 (cobrança PAGA tem o principal quitado, sem pagamento a maior)
WITH pago AS (
    SELECT cob_id, SUM(pag_valor_pago - pag_multa - pag_juros) AS principal_pago
    FROM PAGAMENTO
    GROUP BY cob_id
)
SELECT cb.cob_id, cb.mat_id, cb.cob_tipo, cb.cob_numero_parcela, cb.cob_valor, cb.cob_status,
       IFNULL(p.principal_pago, 0) AS principal_pago,
       CASE WHEN cb.cob_status = 'PAGA' AND IFNULL(p.principal_pago, 0) < cb.cob_valor
                 THEN 'Marcada como PAGA com pagamento insuficiente'
            WHEN IFNULL(p.principal_pago, 0) > cb.cob_valor
                 THEN 'Pagamento acima do valor da cobrança'
            ELSE 'Quitada sem status PAGA' END AS inconsistencia
FROM COBRANCA cb
LEFT JOIN pago p ON p.cob_id = cb.cob_id
WHERE (cb.cob_status = 'PAGA' AND IFNULL(p.principal_pago, 0) < cb.cob_valor)
   OR IFNULL(p.principal_pago, 0) > cb.cob_valor
   OR (cb.cob_status IN ('ABERTA','VENCIDA') AND IFNULL(p.principal_pago, 0) >= cb.cob_valor);

-- A12 Existe professor com mais de 2 turmas no mesmo dia e horário?
-- Verifica: RN06 (professor em até 2 turmas simultâneas)
SELECT pr.pro_nome AS professor,
       h.hor_dia_da_semana AS dia,
       t.tur_hora_inicio AS inicio,
       t.tur_hora_fim AS fim,
       COUNT(DISTINCT t.tur_id) AS turmas_simultaneas,
       GROUP_CONCAT(DISTINCT t.tur_codigo ORDER BY t.tur_codigo SEPARATOR ', ') AS turmas
FROM TURMA t
JOIN PROFESSOR pr ON pr.pro_id = t.pro_id
JOIN TURMA_HORARIO th ON th.tur_id = t.tur_id
JOIN HORARIO_FUNCIONAMENTO h ON h.hor_id = th.hor_id
WHERE t.tur_situacao IN ('ABERTA','EM_ANDAMENTO')
GROUP BY pr.pro_id, pr.pro_nome, h.hor_id, h.hor_dia_da_semana, t.tur_hora_inicio, t.tur_hora_fim
HAVING COUNT(DISTINCT t.tur_id) > 2
ORDER BY pr.pro_nome, h.hor_id;

-- A13 Existe aluno que tinha menos de 14 anos na data da matrícula?
-- Verifica: RN08 (idade mínima de 14 anos)
SELECT m.mat_id, al.alu_nome AS aluno, al.alu_data_nascimento, m.mat_data_registro,
       TIMESTAMPDIFF(YEAR, al.alu_data_nascimento, m.mat_data_registro) AS idade_na_matricula
FROM MATRICULA m
JOIN ALUNO al ON al.alu_id = m.alu_id
WHERE TIMESTAMPDIFF(YEAR, al.alu_data_nascimento, m.mat_data_registro) < 14;

-- A14 Existe turma extra fora de terça/quinta ou fora do intervalo das 10h às 16h?
-- Verifica: RN03 (turma extra só ter/qui entre 10h e 16h)
SELECT t.tur_codigo, t.tur_tipo, t.tur_hora_inicio, t.tur_hora_fim,
       GROUP_CONCAT(h.hor_dia_da_semana ORDER BY h.hor_id SEPARATOR ', ') AS dias
FROM TURMA t
JOIN TURMA_HORARIO th ON th.tur_id = t.tur_id
JOIN HORARIO_FUNCIONAMENTO h ON h.hor_id = th.hor_id
WHERE t.tur_tipo = 'EXTRA'
  AND t.tur_situacao IN ('ABERTA','EM_ANDAMENTO')
GROUP BY t.tur_id, t.tur_codigo, t.tur_tipo, t.tur_hora_inicio, t.tur_hora_fim
HAVING SUM(h.hor_dia_da_semana NOT IN ('TER','QUI')) > 0
    OR t.tur_hora_inicio < '10:00:00'
    OR t.tur_hora_fim > '16:00:00';

-- A15 Existe turma ofertada com curso inativo ou professor inativo?
-- Verifica: RN27 (turma ativa exige curso e professor ativos)
SELECT t.tur_codigo, t.tur_situacao, c.cur_nome AS curso, c.cur_ativo,
       pr.pro_nome AS professor, pr.pro_ativo
FROM TURMA t
JOIN CURSO c      ON c.cur_id = t.cur_id
JOIN PROFESSOR pr ON pr.pro_id = t.pro_id
WHERE t.tur_situacao IN ('ABERTA','EM_ANDAMENTO')
  AND (c.cur_ativo = FALSE OR pr.pro_ativo = FALSE);

-- A16 Existe matrícula ativa em turma encerrada ou cancelada?
-- Verifica: RN28 (turma encerrada ou cancelada não mantém matrícula ativa)
SELECT m.mat_id, al.alu_nome AS aluno, t.tur_codigo, t.tur_situacao, m.mat_status
FROM MATRICULA m
JOIN ALUNO al ON al.alu_id = m.alu_id
JOIN TURMA t  ON t.tur_id = m.tur_id
WHERE m.mat_status = 'ATIVA'
  AND t.tur_situacao IN ('ENCERRADA','CANCELADA');

-- A17 Existe matrícula ativa que nunca gerou cobrança?
-- Verifica: RN29 (matrícula ativa gera cobranças)
SELECT m.mat_id, al.alu_nome AS aluno, t.tur_codigo, m.mat_data_registro
FROM MATRICULA m
JOIN ALUNO al ON al.alu_id = m.alu_id
JOIN TURMA t  ON t.tur_id = m.tur_id
LEFT JOIN COBRANCA cb ON cb.mat_id = m.mat_id
WHERE m.mat_status = 'ATIVA'
  AND cb.cob_id IS NULL;
